using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using UnityEngine;using UnityEngine.Profiling;using Unity.Profiling;using Unity.Profiling.LowLevel.Unsafe;
public static class C1Metrics {
 static byte[] sink;
 [Serializable]class MemoryRow{public string phase;public long allocated,reserved,managedUsed,managedHeap;public int terrainData,activeTerrain,navMeshData,objects,materials,textures;}
 [Serializable]class Summary{public string scope,cpuStatus,drawStatus,gcStatus,gpuStatus;public bool cpuValid,drawValid,frameTimingEnabled;public long positiveGC,zeroGC;public double cpuMeanMs,drawMean;public int samples;}
 public static void Memory(string root,string phase){File.AppendAllText(root+"/map-memory.jsonl",JsonUtility.ToJson(new MemoryRow{phase=phase,allocated=Profiler.GetTotalAllocatedMemoryLong(),reserved=Profiler.GetTotalReservedMemoryLong(),managedUsed=Profiler.GetMonoUsedSizeLong(),managedHeap=Profiler.GetMonoHeapSizeLong(),terrainData=Resources.FindObjectsOfTypeAll<TerrainData>().Length,activeTerrain=UnityEngine.Object.FindObjectsByType<Terrain>().Length,navMeshData=Resources.FindObjectsOfTypeAll<UnityEngine.AI.NavMeshData>().Length,objects=UnityEngine.Object.FindObjectsByType<GameObject>().Length,materials=Resources.FindObjectsOfTypeAll<Material>().Length,textures=Resources.FindObjectsOfTypeAll<Texture>().Length})+"\n");}
 public static IEnumerator Sample(CombatSession session,string root){var handles=new List<ProfilerRecorderHandle>();ProfilerRecorderHandle.GetAvailable(handles);File.WriteAllLines(root+"/metric-units.txt",handles.Select(h=>ProfilerRecorderHandle.GetDescription(h)).Where(d=>d.Name=="Main Thread"||d.Name.Contains("Draw Calls")||d.Name.Contains("GC Allocated")||d.Name.Contains("GPU Frame")).Select(d=>d.Name+"|"+d.UnitType));
  var cpu=ProfilerRecorder.StartNew(ProfilerCategory.Internal,"Main Thread",128);var draw=ProfilerRecorder.StartNew(ProfilerCategory.Render,"Draw Calls Count",128);var timings=new FrameTiming[1];var c=new List<long>();var d=new List<long>();
  long before=GC.GetAllocatedBytesForCurrentThread();sink=new byte[65536];GC.KeepAlive(sink);long positive=GC.GetAllocatedBytesForCurrentThread()-before;before=GC.GetAllocatedBytesForCurrentThread();long zero=GC.GetAllocatedBytesForCurrentThread()-before;
  Memory(root,"steady-map-before-sample");File.WriteAllText(root+"/profiler-frames.csv","frame,cpu_valid,main_thread_ns,draw_valid,draw_calls,gpu_uncalibrated_ms\n");
  for(int i=0;i<100;i++){FrameTimingManager.CaptureFrameTimings();yield return null;uint n=FrameTimingManager.GetLatestTimings(1,timings);long cv=cpu.Valid?cpu.LastValue:0,dv=draw.Valid?draw.LastValue:0;File.AppendAllText(root+"/profiler-frames.csv",Time.frameCount+","+cpu.Valid+","+cv+","+draw.Valid+","+dv+","+(n>0?timings[0].gpuFrameTime:0).ToString("R",System.Globalization.CultureInfo.InvariantCulture)+"\n");if(i>=20){if(cpu.Valid&&cv>0)c.Add(cv);if(draw.Valid&&dv>0)d.Add(dv);}}
  File.WriteAllText(root+"/performance.json",JsonUtility.ToJson(new Summary{scope="steady five-region scene with controlled NPCs, includes HUD and observer overhead; not combat or human benchmark",cpuStatus=c.Count>0?"MEASURED_UNBUDGETED":"NOT_RUN",drawStatus=d.Count>0?"MEASURED_UNBUDGETED":"NOT_RUN",cpuValid=cpu.Valid,drawValid=draw.Valid,cpuMeanMs=c.Count>0?c.Average()/1e6:0,drawMean=d.Count>0?d.Average():0,samples=c.Count,positiveGC=positive,zeroGC=zero,gcStatus=positive>=65536&&zero==0?"CURRENT_THREAD_CONTROL_ONLY":"NOT_RUN",gpuStatus="NOT_RUN: no valid controlled-load calibration in this game workload",frameTimingEnabled=FrameTimingManager.IsFeatureEnabled()},true));cpu.Dispose();draw.Dispose();Memory(root,"steady-map-after-sample");
 }
}
